param([string]$OutFile,[int]$Seconds=30)
Write-Host "Midiendo $Seconds segundos...";$a=Get-Process|Select-Object Id,ProcessName,CPU,WorkingSet64;Start-Sleep -Seconds $Seconds;$b=Get-Process|Select-Object Id,ProcessName,CPU,WorkingSet64;$r=foreach($x in $b){$old=$a|Where-Object Id -eq $x.Id|Select-Object -First 1;if($old){[pscustomobject]@{Proceso=$x.ProcessName;CPU_s=[math]::Round(($x.CPU-$old.CPU),2);RAM_MB=[math]::Round($x.WorkingSet64/1MB,0)}}};$top=$r|Sort-Object CPU_s -Descending|Select-Object -First 15;@('WINTOOL V5 - CARGA DE SEGUNDO PLANO','')+($top|Format-Table -AutoSize|Out-String)+@('','Solo lectura. WinTool no cambia prioridades.')|Set-Content $OutFile -Encoding UTF8
